INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','verb-pattern-meaning','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"verb-pattern-meaning","title":"Verb patterns that change meaning","level":"B2","order":54,"summary":"Distinguish remembering a duty from recalling an experience, stopping an action from pausing for a purpose, and methods from attempts.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Remember a duty or recall an experience","Stop one activity or pause for another","Try a method or attempt a difficult action","Go on and regret"],"rules":[{"title":"Remember a duty or recall an experience","explanation":"**Remember to do** means remembering a necessary action before doing it. **Remember doing** means recalling an earlier experience. The same contrast often appears with forget, although a negative such as I’ll never forget meeting her is especially common.","pattern":"Remember **to lock** the door. / I remember **locking** it.","commonMistakes":["The -ing form refers to the remembered experience; it is not simply an alternative spelling of the infinitive."],"examples":["The task is still ahead. Complete the reminder: “Please remember **to prepare** the visitor guide.”","The task is still ahead. Complete the reminder: “Please remember **to restore** the old portrait.”"],"skill":"form"},{"title":"Stop one activity or pause for another","explanation":"**Stop doing** means cease that activity. **Stop to do** means interrupt another activity in order to do this one. The second pattern is an infinitive of purpose, so it answers why the person paused.","pattern":"We stopped **talking**. / We stopped **to talk**.","commonMistakes":["Stopped to smoke does not mean quit smoking; it means paused in order to smoke."],"examples":["The task happened yesterday and I recall doing it: “I remember **preparing** the visitor guide.”","The task happened yesterday and I recall doing it: “I remember **restoring** the old portrait.”"],"skill":"meaning"},{"title":"Try a method or attempt a difficult action","explanation":"**Try doing** often suggests testing a method to see if it helps. **Try to do** emphasises making an attempt, which may fail. Some contexts allow both with little practical difference, so tasks need a clear intention.","pattern":"Try **restarting** it. / I tried **to lift** it but could not.","commonMistakes":["Do not assume that try + -ing always succeeded; it describes the method being tested."],"examples":["They ceased this activity completely: “They stopped **preparing** the visitor guide.”","They ceased this activity completely: “They stopped **restoring** the old portrait.”"],"skill":"contrast"},{"title":"Go on and regret","explanation":"Go on doing continues the same activity; go on to do moves to a new activity. Regret doing looks back with regret, while regret to inform is a conventional way to introduce unwelcome information. Learn these as meaning-and-form pairs.","pattern":"She went on **speaking**. / She went on **to explain** the next step.","commonMistakes":["Not every verb accepts both patterns. Avoid transferring these contrasts to verbs such as enjoy, which normally takes -ing."],"examples":["We interrupted our walk in order to do the task: “We stopped **to prepare** the visitor guide.”","We interrupted our walk in order to do the task: “We stopped **to restore** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Distinguish remembering a duty from recalling an experience, stopping an action from pausing for a purpose, and methods from attempts.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Remember a duty or recall an experience","explanation":"**Remember to do** means remembering a necessary action before doing it. **Remember doing** means recalling an earlier experience. The same contrast often appears with forget, although a negative such as I’ll never forget meeting her is especially common.","pattern":"Remember **to lock** the door. / I remember **locking** it.","commonMistakes":["The -ing form refers to the remembered experience; it is not simply an alternative spelling of the infinitive."],"examples":["The task is still ahead. Complete the reminder: “Please remember **to prepare** the visitor guide.”","The task is still ahead. Complete the reminder: “Please remember **to restore** the old portrait.”"],"skill":"form","id":"verb-pattern-meaning-foundation-1","domain":"nonfinite","referenceIds":["bc-verb-meaning"],"readingVersion":"core-2026-09-v3"},{"title":"Stop one activity or pause for another","explanation":"**Stop doing** means cease that activity. **Stop to do** means interrupt another activity in order to do this one. The second pattern is an infinitive of purpose, so it answers why the person paused.","pattern":"We stopped **talking**. / We stopped **to talk**.","commonMistakes":["Stopped to smoke does not mean quit smoking; it means paused in order to smoke."],"examples":["The task happened yesterday and I recall doing it: “I remember **preparing** the visitor guide.”","The task happened yesterday and I recall doing it: “I remember **restoring** the old portrait.”"],"skill":"meaning","id":"verb-pattern-meaning-foundation-2","domain":"nonfinite","referenceIds":["bc-verb-meaning"],"readingVersion":"core-2026-09-v3"},{"title":"Try a method or attempt a difficult action","explanation":"**Try doing** often suggests testing a method to see if it helps. **Try to do** emphasises making an attempt, which may fail. Some contexts allow both with little practical difference, so tasks need a clear intention.","pattern":"Try **restarting** it. / I tried **to lift** it but could not.","commonMistakes":["Do not assume that try + -ing always succeeded; it describes the method being tested."],"examples":["They ceased this activity completely: “They stopped **preparing** the visitor guide.”","They ceased this activity completely: “They stopped **restoring** the old portrait.”"],"skill":"contrast","id":"verb-pattern-meaning-foundation-3","domain":"nonfinite","referenceIds":["bc-verb-meaning"],"readingVersion":"core-2026-09-v3"},{"title":"Go on and regret","explanation":"Go on doing continues the same activity; go on to do moves to a new activity. Regret doing looks back with regret, while regret to inform is a conventional way to introduce unwelcome information. Learn these as meaning-and-form pairs.","pattern":"She went on **speaking**. / She went on **to explain** the next step.","commonMistakes":["Not every verb accepts both patterns. Avoid transferring these contrasts to verbs such as enjoy, which normally takes -ing."],"examples":["We interrupted our walk in order to do the task: “We stopped **to prepare** the visitor guide.”","We interrupted our walk in order to do the task: “We stopped **to restore** the old portrait.”"],"skill":"application","id":"verb-pattern-meaning-foundation-4","domain":"nonfinite","referenceIds":["bc-verb-meaning"],"readingVersion":"core-2026-09-v3"},{"domain":"nonfinite","id":"remember-forget-regret","title":"Remember, forget and regret: time and meaning","explanation":"Remember or forget + to-infinitive concerns a duty or intended action. Remember + -ing recalls an experience; never forget + -ing highlights a memorable one. Regret + -ing looks back with regret, while regret to say/inform conventionally introduces bad news. The complement changes the relation between the mental event and the other action.","pattern":"remember **to call** / remember **calling**","examples":["I forgot **to lock** the door.","I regret **telling** him, but I regret **to inform** you that it is too late."],"commonMistakes":["Remembering to do something normally implies that the action is carried out in the relevant narrative; merely thinking about an intended future duty may need different wording."],"referenceIds":["cambridge-nonfinite-scope","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"nonfinite","id":"try-go-on-mean","title":"Try, go on, mean and need with different complements","explanation":"Try + -ing can test a method; try + to-infinitive emphasises an attempt. Go on + -ing continues an activity; go on + to-infinitive introduces a later one. Mean + to-infinitive expresses intention; mean + -ing presents a consequence. Need + -ing can have passive meaning in relevant varieties and contexts.","pattern":"try **restarting** / try **to restart**","examples":["He went on **talking**, then went on **to discuss** the budget.","The floor needs **cleaning** means it needs **to be cleaned**."],"commonMistakes":["Some contexts allow both complements with little practical difference. Do not force a dramatic meaning contrast where the surrounding situation does not support one."],"referenceIds":["cambridge-nonfinite-scope","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["Remember **to lock** the door. / I remember **locking** it.","We stopped **talking**. / We stopped **to talk**.","Try **restarting** it. / I tried **to lift** it but could not.","She went on **speaking**. / She went on **to explain** the next step."],"readingVersion":"core-2026-09-v4"},"stage":"5 · Complex sentences","prerequisites":["reflexive-reciprocal"],"readingReferenceIds":["bc-verb-meaning","cambridge-nonfinite-scope","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='verb-pattern-meaning'
